function planMarkup(level,mini=false){
 const site=[[7.947,.568],[33.895,0],[38.031,28.706],[0,25.138]],fp=[[10.775,3.635],[30.619,3.200],[33.781,25.152],[4.698,22.424]];
 const P=([x,y])=>[65+x*12,95+y*12];const points=a=>a.map(p=>P(p).join(',')).join(' ');
 let s='<defs><clipPath id="cut'+level+(mini?'m':'')+'"><polygon points="'+points(fp)+'"/></clipPath></defs>';
 s+='<polygon points="'+points(site)+'" fill="#d1dfc7" stroke="#6c8264" stroke-width="2"/>';
 s+='<polygon points="'+points(fp)+'" fill="#ece7db" stroke="#997752" stroke-width="3"/>';
 s+='<g clip-path="url(#cut'+level+(mini?'m':'')+')">';
 function box(x,y,w,h,label,fill='#b8c9ad'){let [xx,yy]=P([x,y]);s+=`<rect x="${xx}" y="${yy}" width="${w*12}" height="${h*12}" rx="2" fill="${fill}" stroke="#f5f1e9" stroke-width="2"/><text x="${xx+w*6}" y="${yy+h*6}" text-anchor="middle" dominant-baseline="middle" fill="#30402e" font-size="${mini?0:9}">${label}</text>`}
 function band(y0,y1,n,labels,color){function edge(y,left){let a=left?fp[0]:fp[1],b=left?fp[3]:fp[2];return a[0]+(b[0]-a[0])*(y-a[1])/(b[1]-a[1])}let l0=edge(y0,true),l1=edge(y1,true),r0=edge(y0,false),r1=edge(y1,false);for(let j=0;j<n;j++){let a=l0+(r0-l0)*j/n,b=l0+(r0-l0)*(j+1)/n,d=l1+(r1-l1)*j/n,e=l1+(r1-l1)*(j+1)/n;s+='<polygon points="'+points([[a,y0],[b,y0],[e,y1],[d,y1]])+'" fill="'+color+'" stroke="#f5f1e9" stroke-width="2"/>';if(!mini){let [tx,ty]=P([(a+b+d+e)/4,(y0+y1)/2]);s+=`<text x="${tx}" y="${ty}" text-anchor="middle" font-size="9" fill="#30402e">${labels[j]||''}</text>`}}}
 if(level==='P'){for(let r=0;r<2;r++)for(let j=0;j<6;j++)box(12+j*2.7,6+r*9,2.7,5.5,String(r*6+j+1).padStart(2,'0'),'#9cafb4');box(12,11.5,16.2,3.5,'SHUTTLE / TRANSFER','#eaf0ed');box(28.5,16,4,7,'LIFT / SERVIS','#c8b89c')}
 else if(level===0){box(12,5,7,7,'KABIN TRANSFER','#95acb2');box(20,5,10,8,'LOBBY / WC','#d1b995');box(10,13,18,5,'ANTRE / MANUVER','#ffffff');box(8,18,10,5,'UTILITY','#a6b5a2');box(19,18,10,5,'MOTOR / SERVIS','#a6b5a2')}
 else if(level===1){band(4,10.5,4,['101','102','103','104'],'#b8c9ad');band(10.5,12.5,1,['KORIDOR'],'#fff');box(10,13,11,8,'POOL + DECK','#aec9c5');box(11,15,8,3,'AIR 8 × 3 m','#65a8b1');box(22,13,9,5,'GYM','#acbd96');box(21,18,5,4,'OFFICE','#d1b995');box(26,18,6,4,'MEETING','#d1b995')}
 else if(level<5){band(4,11,6,Array.from({length:6},(_,j)=>level+'0'+(j+1)),'#b8c9ad');band(11,13,1,['KORIDOR UTAMA'],'#fff');band(13,20,6,Array.from({length:6},(_,j)=>level+String(j+7).padStart(2,'0')),'#b8c9ad');band(20,22,1,['LOBBY / SIRKULASI / SERVIS'],'#e5d7bb')}
 else{band(4,10,1,['TERAS HIJAU'],'#a5bd94');band(10,18,1,['DINING / CAFE'],'#d7c09a');band(18,22,3,['BAR','KITCHEN','WC / STORE'],'#a6b5a2')}
 if(level!=='P'){box(10,4,3.5,4.5,'TA','#7f9582');box(28,20,3.5,4.5,'TB','#7f9582');box(24,21,3.5,3.5,'LIFT','#7f9582')}
 s+='</g>';
 if(!mini)s+='<text x="300" y="35" text-anchor="middle" font-size="15" fill="#30402e">LAHAN EXISTING 855 m²</text><text x="300" y="56" text-anchor="middle" font-size="10" fill="#60715b">Proporsi ditelusuri dari gambar ukur • utara belum diketahui</text><text x="320" y="85" text-anchor="middle" font-size="11" fill="#52634f">sisi ±26 m</text><text x="530" y="265" font-size="11" fill="#52634f" transform="rotate(82 530 265)">belakang ±29 m</text><text x="300" y="470" text-anchor="middle" font-size="11" fill="#52634f">sisi panjang ±38 m</text><text x="74" y="280" font-size="11" fill="#52634f" transform="rotate(-72 74 280)">Jl. Setrasari Raya / muka ±26 m</text><text x="300" y="510" text-anchor="middle" font-size="11" fill="#52634f">Massa konsep 500 m² • KDB 58,48% • setback bukan GSB legal</text><text x="300" y="532" text-anchor="middle" font-size="10" fill="#52634f">'+(level==='P'?'12 posisi ilustratif / tier × 3 = target 36; slot usable belum tervalidasi':'Zona skematik: luas kamar & sirkulasi perlu test-fit ulang')+'</text><text x="300" y="555" text-anchor="middle" font-size="10" fill="#52634f">Angka panjang sisi perkiraan proporsi, bukan ukuran survei.</text>';
 return s}
